    private void cantidadKeyTyped(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_cantidadKeyTyped
        char c = evt.getKeyChar();
        if(c<'0' || c>'9') if(c!='.')evt.consume();
    }//GEN-LAST:event_cantidadKeyTyped

