    private void precioKeyTyped(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_precioKeyTyped
        char c = evt.getKeyChar();
        if(c<'0' || c>'9') if(c!='.')evt.consume();
    }//GEN-LAST:event_precioKeyTyped

    
